/*
A = `if` `return` `while`
                    where
                    `if`:scalar
                    `return`:scalar
                    `while`:scalar
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT A;

    heartlib(
        const double & _if,
        const double & _return,
        const double & _while)
    {

        // A = `if` `return` `while`
        A = _if * _return * _while;
    }
};

