outputs.matlab:
function output = heartlib(if_, return_, while_)
% output = heartlib(`if`, `return`, `while`)
%
%    A = `if` `return` `while`
%                        where
%                        `if`:scalar
%                        `return`:scalar
%                        `while`:scalar
    assert(numel(if_) == 1);
    assert(numel(return_) == 1);
    assert(numel(while_) == 1);

    % A = `if` `return` `while`

    A = if_ * return_ * while_;
    output.A = A;
end

